import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data/guide-catalog.json'
data=json.loads(p.read_text())
# Each recommendation is either backed by a named launch-week guide or explicitly framed as an evaluation checklist.
SOURCES={
 'powerpyx-money':('PowerPyx — GTA 6 Money Guide','https://www.powerpyx.com/gta-6-money-guide-how-to-get-money-fast'),
 'pcgamer-money':('PC Gamer — Fastest ways to make money','https://www.pcgamer.com/games/grand-theft-auto/gta-6-how-to-make-money/'),
 'gtabase-money':('GTA Base — Money-making methods','https://www.gtabase.com/gta-6/articles/how-to-make-money-fast-in-gta-6'),
 'guardian':('The Guardian — 15 playing tips','https://www.theguardian.com/games/2026/nov/19/tips-for-playing-grand-theft-auto-vi'),
 'powerpyx-walk':('PowerPyx — Full missions walkthrough','https://www.powerpyx.com/gta-6-full-walkthrough-all-missions/'),
 'sixtrack':('SixTrack — Story walkthrough','https://sixtrack.app/gta6/walkthrough/'),
 'gtabase-cars':('GTA Base — Best cars database','https://www.gtabase.com/gta-6/vehicles/'),
 'gtabase-planes':('GTA Base — Plane comparisons','https://www.gtabase.com/gta-6/vehicles/best-planes/'),
 'gtabase-boats':('GTA Base — Boat comparisons','https://www.gtabase.com/gta-6/vehicles/best-boats/'),
 'timesaver-cars':('Timesaver — vehicle speed-stat comparison','https://timesaver.gg/tools/gta-6/cars/fastest'),
}

def add(id,title,category,summary,body,tags,steps,source_keys=[],spoiler=False,stage='',vehicleClass='',confidence='reported',recommendation=''):
    sources=[{'label':SOURCES[k][0], 'url':SOURCES[k][1]} for k in source_keys]
    data.append(dict(id=id,title=title,category=category,summary=summary,body=body,region='General',sourceType='community' if source_keys else 'template',sourceUrl=sources[0]['url'] if sources else None,sourceLabel=sources[0]['label'] if sources else None,sources=sources,spoiler=spoiler,tags=tags,steps=[dict(id=f't{i}',label=step) for i,step in enumerate(steps,1)],stage=stage,vehicleClass=vehicleClass,confidence=confidence if source_keys else 'template',recommendation=recommendation))

add('money-stolen-cars','Quick cash: sell stolen cars','Money','Chapter 2: an accessible, repeatable early cash route after unlocking Moses.','Launch-week walkthroughs report that Moses buys stolen vehicles after his Chapter 2 introduction. Compare vehicle value, travel time, police attention and sale cooldown. Avoid assuming every car is eligible; this is a reported strategy, not a guaranteed payout.', ['money','cars','chapter-2','earnings','starter'],['Complete the story mission that introduces Moses','Find an eligible vehicle without drawing attention','Deliver it and record your actual payout','Repeat only if it beats your other options'],['powerpyx-money','pcgamer-money','gtabase-money'],stage='Chapter 2+',confidence='reported',recommendation='EARLY-GAME PICK')
add('money-vault-jobs','High-reward: vault robberies','Money','A late-game candidate for high payouts with significant police risk.','GTA Base and PowerPyx describe bank vault robberies as a strong later-game earner. Treat payout figures as variable. Prepare escape vehicles and compare profit per minute after heat, ammunition and failure costs.', ['money','robberies','late-game','high-risk'],['Unlock vault robbery access','Prepare escape route and spare vehicle','Complete a job and record payout','Compare cash earned per minute'],['powerpyx-money','gtabase-money'],spoiler=True,stage='Later chapters',confidence='reported',recommendation='HIGH-REWARD PICK')
add('money-safe-first-hour','First-hour cash discipline','Money','Protect the money you earn before investing in expensive vehicles.','Launch-week advice recommends banking cash rather than keeping large amounts on hand, planning low-risk escapes, and avoiding unnecessary vehicle damage. Your exact financial options depend on story progression; verify them in your save.', ['money','beginner','banking','risk'],['Check when your account or payment app becomes available','Deposit earnings when possible','Keep a modest reserve for equipment and travel','Compare earnings before buying a luxury vehicle'],['guardian','gtabase-money'],stage='Early game',confidence='reported',recommendation='START HERE')
add('money-quick-robberies','Opportunistic robberies','Money','Evaluate small robberies and open-world crimes against their heat and time cost.','Launch-week guides describe shop jobs and incidental open-world criminal opportunities. The recommended strategy is to evaluate a net return: payout minus recovery time, wanted level and equipment costs. Do not treat any listed encounter as a guaranteed spawn.', ['money','side-activities','robberies'],['Find a lower-risk opportunity','Plan an exit without using your personal vehicle','Record cash received and time elapsed','Compare against car-selling income'],['pcgamer-money','guardian'],stage='Chapter 1+',confidence='reported')
add('story-spoiler-safe-route','Story route without spoilers','Story','A chapter-by-chapter progress outline with minimal narrative detail.','Play main missions in order, while checking the map for time-sensitive side content before advancing major story beats. Mission lists can vary depending on whether brief tasks and optional activities are counted. Use the linked walkthrough for actual sequence details, with spoilers revealed only when you choose.', ['story','chapters','walkthrough','beginner'],['Finish the prologue','Complete Chapter 1 missions at your pace','Before changing chapters, check optional content','Record Chapter 2 completion','Record Chapters 3–5 completion'],['powerpyx-walk','sixtrack'],stage='All chapters',confidence='reported',recommendation='SPOILER-SAFE ROUTE')
add('story-before-point-of-no-return','Before a point of no return','Story','Save, bank money, and check optional activities before story lockouts.','Player walkthroughs identify certain transition missions that change access to characters, areas or carried resources. Do not assume you can freely replay missions. Consult the linked chapter guide before committing if you want a completionist route.', ['story','missables','chapter-1','warning'],['Make a manual save if available','Check marked side missions and activities','Bank or safely store valuables as available','Read the upcoming mission warning in the linked guide'],['powerpyx-walk','sixtrack'],spoiler=True,stage='Chapter transitions',confidence='reported',recommendation='MISSABLES WARNING')
add('story-chapter-checkpoints','Five-chapter journey tracker','Story','Track your story completion by chapter without exposing mission titles.','This is a private checklist organizer for the five reported chapters of the main story. It is intentionally broad; detailed mission breakdowns will be added as individual missions are independently confirmed and sourced.', ['story','progress','spoiler-free','tracker'],['Chapter 1','Chapter 2','Chapter 3','Chapter 4','Chapter 5'],['powerpyx-walk'],stage='All chapters',confidence='reported')
add('story-side-quests','Optional activity sweep','Story','Avoid leaving useful side jobs, contacts, or collectibles behind.','Before advancing a major story beat, use this repeatable checklist to review map markers, active contacts, and unfinished optional quests. The app does not assert that every item is permanently missable.', ['story','side-quests','completionist'],['Check map for optional symbols','Follow up with contacts','Review region-specific collectibles','Record pending activities in personal notes'],['sixtrack','powerpyx-walk'],stage='Every chapter',confidence='reported')
add('cars-top-speed-watch','Fast road cars: emerging picks','Vehicles','Performance comparisons are preliminary; prioritize measured handling and speed.','Launch-week lists disagree on the fastest overall car. Look at candidates such as the Progen Emerus and Pfister Comet S2, but do not infer real top speeds from unverified online estimates. iVice will distinguish in-game stat ratings, tested runs, and anecdotal rankings.', ['cars','performance','supercars','fastest'],['Compare current in-game speed and handling stats','Try each candidate on the same route','Record vehicle and tuning state','Save the car you actually prefer'],['timesaver-cars','gtabase-cars'],vehicleClass='Car',stage='After access',confidence='reported',recommendation='PERFORMANCE WATCHLIST')
add('cars-practical-getaway','Best getaway car: by job','Vehicles','A reliable four-door car can beat a faster two-seater for risky missions.','There is no universal best getaway car. Rank choices by seats, braking, damage tolerance, anonymity, and how easily you can replace them. Use the same escape route for apples-to-apples comparisons.', ['cars','getaway','best','handling'],['Choose car with enough seats','Practice braking and cornering','Test police-escape route','Store a backup outside the mission area'],['guardian','gtabase-cars'],vehicleClass='Car',stage='Any time',confidence='reported',recommendation='PRACTICAL PICK')
add('vehicles-aircraft','Planes & helicopters: buyer’s guide','Vehicles','Compare aircraft by access, landing room, flight stability and speed.','Current public aircraft lists are still being tested. Rather than declare an unverified fastest jet, compare available aircraft for the job: fixed-wing for long routes, helicopter for flexible landings, and utility aircraft for exploration.', ['airplanes','planes','helicopter','jets','aircraft'],['Log aircraft you have access to','Record acquisition location','Compare takeoff distance and landing options','Add a personal speed and handling note'],['gtabase-planes'],vehicleClass='Aircraft',stage='When unlocked',confidence='reported',recommendation='AIRCRAFT GUIDE')
add('vehicles-speedboats','Speedboats: coastal travel picks','Vehicles','Choose watercraft based on coastal runs, handling and passenger needs.','Boat rankings are still being compiled and published data may differ across sources. Compare fast open-water craft, nimble inflatables and airboats for wetlands. No unsourced top-speed figure is presented as a verified GTA VI measurement.', ['boats','speedboats','watercraft','coast'],['Identify a fast open-water boat','Test turning and braking in a narrow channel','Compare passenger capacity','Record the best boat for your route'],['gtabase-boats'],vehicleClass='Boat',stage='When unlocked',confidence='reported',recommendation='WATERCRAFT GUIDE')
add('vehicles-offroad','Off-road and swamp vehicles','Vehicles','Prioritize suspension, terrain control and access in rural Leonida.','A fast highway car may perform poorly on unpaved trails and wet terrain. Compare practical utility vehicles and specialized water/airboats by the terrain you actually travel.', ['cars','offroad','swamp','terrain','vehicles'],['Pick a test route in an off-road area','Try an off-road-oriented vehicle','Compare traction and stability','Save vehicle and location in notes'],['gtabase-cars','gtabase-boats'],vehicleClass='Off-road',stage='Any time',confidence='reported')
# Remove any repeated generated entries for idempotency
seen={};
for item in data: seen[item['id']]=item
p.write_text(json.dumps(list(seen.values()),ensure_ascii=False,indent=2)+'\n')
print('catalog:',len(seen),'entries')
